#ifndef __NUITKA_HELPER_NITRO_ATTRIBUTES_H__
#define __NUITKA_HELPER_NITRO_ATTRIBUTES_H__

// nuitka_offsets.h is generated by LayoutOracle at the start of each Zig build
// and lives in nuitka_src/static_src/ (which is in CPPPATH).  We gate on __ZIG__
// because the file does not exist for non-Zig builds.
#ifdef __ZIG__
#include "nuitka_offsets.h"
#endif

#ifdef __NUITKA_DMA_ACTIVE__

// ---------------------------------------------------------------------------
// Nitro-Bypass: fast instance-dict lookup that avoids MRO search and
// descriptor check.  Four tiers, selected at compile time by LayoutOracle:
//
//  Tier 0 (NUITKA_USE_VALUES_ARRAY):
//    Python 3.14+ inline-values layout.  _PyObject_GetInstanceAttribute is
//    used for string keys when inline values are live; falls through to the
//    materialised dict (via _PyObject_GetDictPtr) or to PyObject_GetAttr.
//
//  Tier 1 (NUITKA_HAS_FIXED_DICT_OFFSET, Python 3.14 managed-dict,
//           NITRO_FIXED_OFFSET < 0):
//    The dict pointer lives before the object base — zero tp_dictoffset load.
//
//  Tier 2 (NUITKA_HAS_FIXED_DICT_OFFSET, traditional positive offset):
//    The dict pointer is at a known positive offset — zero tp_dictoffset load.
//
//  Tier 1.5 (NUITKA_MANAGED_DICT, no NUITKA_HAS_FIXED_DICT_OFFSET):
//    Managed dict whose offset was not probed at build time.
//    _PyObject_GetDictPtr handles the layout safely.
//
//  Tier 3 (fallback):
//    Read tp_dictoffset at runtime — one extra memory load.
//
// All tiers gate on tp_getattro == PyObject_GenericGetAttr and fall through to
// PyObject_GetAttr for descriptors, class attributes, __getattr__, and any
// object whose type does not use the generic implementation.
//
// CORRECTNESS NOTE: This function checks the instance dict BEFORE checking for
// data descriptors.  It is semantically correct only when called from code paths
// where the optimizer has verified that no data descriptor shadows the attribute.
// For general attribute lookup use LOOKUP_ATTRIBUTE, which checks descriptors first.
// ---------------------------------------------------------------------------

static inline PyObject *Nuitka_Nitro_GetAttr(PyObject *obj, PyObject *attr_name) {
    PyTypeObject *type = Py_TYPE(obj);

    if (likely(type->tp_getattro == PyObject_GenericGetAttr_resolved)) {

#if defined(NUITKA_USE_VALUES_ARRAY)

        // Tier 0: inline values — fastest for string keys on Python 3.14+.
        if (likely(PyUnicode_CheckExact(attr_name))) {
            PyDictValues *values = *_PyObject_ValuesPointer(obj);

            if (values != NULL) {
                PyObject *result = _PyObject_GetInstanceAttribute(obj, values, attr_name);

                if (result != NULL || unlikely(PyErr_Occurred())) {
                    return result;
                }
                // Key absent from inline values; fall through to class-attr path.
                goto nitro_fallback;
            }
        }

        // Non-string key or values pointer is NULL (dict has been materialised).
        {
            PyObject **dictptr = _PyObject_GetDictPtr(obj);

            if (dictptr != NULL && *dictptr != NULL) {
                PyObject *result = PyDict_GetItemWithError(*dictptr, attr_name);

                if (result != NULL) {
                    Py_INCREF(result);
                    return result;
                }
                if (unlikely(PyErr_Occurred())) {
                    return NULL;
                }
            }
        }

#elif defined(NUITKA_HAS_FIXED_DICT_OFFSET)

        // Tier 1 / Tier 2: compile-time offset — no tp_dictoffset load.
        {
            PyObject **dictptr = (PyObject **)((char *)obj + (NITRO_FIXED_OFFSET));

            if (*dictptr != NULL) {
                PyObject *result = PyDict_GetItemWithError(*dictptr, attr_name);

                if (result != NULL) {
                    Py_INCREF(result);
                    return result;
                }
                if (unlikely(PyErr_Occurred())) {
                    return NULL;
                }
            }
        }

#elif defined(NUITKA_MANAGED_DICT)

        // Tier 1.5: managed dict whose offset was not probed — use _PyObject_GetDictPtr.
        {
            PyObject **dictptr = _PyObject_GetDictPtr(obj);

            if (dictptr != NULL && *dictptr != NULL) {
                PyObject *result = PyDict_GetItemWithError(*dictptr, attr_name);

                if (result != NULL) {
                    Py_INCREF(result);
                    return result;
                }
                if (unlikely(PyErr_Occurred())) {
                    return NULL;
                }
            }
        }

#else

        // Tier 3: runtime tp_dictoffset read — one extra memory load.
        {
            Py_ssize_t dictoffset = type->tp_dictoffset;

            if (dictoffset > 0) {
                PyObject **dictptr = (PyObject **)((char *)obj + dictoffset);

                if (*dictptr != NULL) {
                    PyObject *result = PyDict_GetItemWithError(*dictptr, attr_name);

                    if (result != NULL) {
                        Py_INCREF(result);
                        return result;
                    }
                    if (unlikely(PyErr_Occurred())) {
                        return NULL;
                    }
                }
            }
        }

#endif  // tier selection

    }

nitro_fallback:
    // Descriptor, class attribute, __getattr__, or missing attribute.
    return PyObject_GetAttr(obj, attr_name);
}

static inline bool Nuitka_Nitro_SetAttr(PyObject *target, PyObject *attr_name, PyObject *value) {
    PyTypeObject *type = Py_TYPE(target);

    if (likely(type->tp_setattro == PyObject_GenericSetAttr_resolved)) {

#if defined(NUITKA_HAS_FIXED_DICT_OFFSET)
        // Tier 1 / Tier 2: compile-time offset — no tp_dictoffset load.
        PyObject **dictptr = (PyObject **)((char *)target + (NITRO_FIXED_OFFSET));
#elif defined(NUITKA_MANAGED_DICT)
        // Tier 1.5: managed dict — use _PyObject_GetDictPtr.
        PyObject **dictptr = _PyObject_GetDictPtr(target);
#else
        // Tier 3: runtime tp_dictoffset read — one extra memory load.
        PyObject **dictptr = NULL;
        Py_ssize_t dictoffset = type->tp_dictoffset;

        if (dictoffset > 0) {
            dictptr = (PyObject **)((char *)target + dictoffset);
        }
#endif

        if (dictptr != NULL) {
// _PyObjectDict_SetItem is an internal CPython symbol not exported from the
// shared library on Python 3.14+. Only call it when we have static-lib access
// (_NUITKA_USE_UNEXPOSED_API) or on Python <= 3.13 where it is still exported.
#if PYTHON_VERSION >= 0x300 && (PYTHON_VERSION < 0x3e0 || defined(_NUITKA_USE_UNEXPOSED_API))
            if ((type->tp_flags & Py_TPFLAGS_HEAPTYPE) && (CACHED_KEYS(type) != NULL)) {
#if PYTHON_VERSION >= 0x3d0
                int res = _PyObjectDict_SetItem(type, target, dictptr, attr_name, value);
#else
                int res = _PyObjectDict_SetItem(type, dictptr, attr_name, value);
#endif
                return res >= 0;
            }
#endif
            PyObject *dict = *dictptr;

            if (dict != NULL) {
                return PyDict_SetItem(dict, attr_name, value) == 0;
            }
        }
    }

    return PyObject_SetAttr(target, attr_name, value) == 0;
}

static inline bool Nuitka_Nitro_DelAttr(PyObject *target, PyObject *attr_name) {
    PyTypeObject *type = Py_TYPE(target);

    if (likely(type->tp_setattro == PyObject_GenericSetAttr_resolved)) {

#if defined(NUITKA_HAS_FIXED_DICT_OFFSET)
        // Tier 1 / Tier 2: compile-time offset — no tp_dictoffset load.
        PyObject **dictptr = (PyObject **)((char *)target + (NITRO_FIXED_OFFSET));
#elif defined(NUITKA_MANAGED_DICT)
        // Tier 1.5: managed dict — use _PyObject_GetDictPtr.
        PyObject **dictptr = _PyObject_GetDictPtr(target);
#else
        // Tier 3: runtime tp_dictoffset read — one extra memory load.
        PyObject **dictptr = NULL;
        Py_ssize_t dictoffset = type->tp_dictoffset;

        if (dictoffset > 0) {
            dictptr = (PyObject **)((char *)target + dictoffset);
        }
#endif

        if (dictptr != NULL) {
            PyObject *dict = *dictptr;

            if (dict != NULL) {
                return PyDict_DelItem(dict, attr_name) == 0;
            }
        }
    }

    return PyObject_DelAttr(target, attr_name) == 0;
}

static inline PyObject **Nuitka_Nitro_GetWeakrefListPtr(PyObject *obj) {
#if defined(NUITKA_HAS_FIXED_WEAKREF_OFFSET)
    // Tier 1 / Tier 2: compile-time offset — no tp_weaklistoffset load.
    return (PyObject **)((char *)obj + (NITRO_FIXED_WEAKREF_OFFSET));
#else
    PyTypeObject *type = Py_TYPE(obj);
    Py_ssize_t offset = type->tp_weaklistoffset;

    if (offset > 0) {
        return (PyObject **)((char *)obj + offset);
    }
#if defined(NUITKA_MANAGED_WEAKREF)
    // Tier 1.5: managed weakref but offset was not probed.
    // Fall back to standard macro if available, or NULL.
    return _PyObject_GET_WEAKREFS_LISTPTR(obj);
#else
    return NULL;
#endif
#endif
}

#endif /* __NUITKA_DMA_ACTIVE__ */

#endif /* __NUITKA_HELPER_NITRO_ATTRIBUTES_H__ */

